import {PHYSICAL_LORE} from './physical-lore-content.js';
/** All prices are in-game credits. Finite chapter markets; no wall-clock resets. */
import {REGIONS} from './regional-content.js?v=5.16.0';
export const GOODS=[{id:'metal',name:'Reclaimed metal',glyph:'⚒',color:'#d3a57d'},{id:'fiber',name:'Living fibre',glyph:'❧',color:'#99c49a'},{id:'glass',name:'Resonant glass',glyph:'◇',color:'#9ec9e4'}];
export const CIVIC_WORKS=[{id:'water',name:'Clean-water cooperative',good:'glass',text:'Essential remedies cost 15% less here. Households maintain a public water point.'},{id:'workshop',name:'Open repair workshop',good:'metal',text:'Crafting here needs one fewer material. Grounded work areas soften Volt damage for both sides in local battles.'},{id:'commons',name:'Neighbourhood commons',good:'fiber',text:'Local deliveries pay 15% more. Travellers begin local battles with 15 shield and recover 2 extra MP when guarding.'}];
export const RECIPES=[{id:'wrap',name:'Trail medicine',good:'fiber',cost:2,item:'mossWrap',chapter:1},{id:'rain',name:'Water carrier',good:'glass',cost:2,item:'tideFlask',chapter:2},{id:'ember',name:'Heat capsule',good:'metal',cost:2,item:'emberBomb',chapter:3},{id:'clean',name:'Keeper’s remedy',good:'fiber',cost:3,item:'greenPoultice',chapter:4},{id:'echo',name:'Focus collector',good:'glass',cost:3,item:'echoSponge',chapter:6},{id:'breaker',name:'Railbreaker charge',good:'metal',cost:4,item:'shatterCharge',chapter:10}];
export const STAMPS=[{id:'first-road',at:1,name:'First Road seal',text:'Your first protected shipment. A unique mark of a road kept open.'},{id:'three-hands',at:3,name:'Three Hands seal',text:'Three deliveries connect the makers. Two shipments may now travel together.'},{id:'common-thread',at:6,name:'Common Thread seal',text:'Six deliveries. Participating markets hold two extra specialist supplies each chapter.'}];
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),chapter=s=>clamp(Math.floor(s.chapter||1),1,24);
export const economyRegion=w=>clamp(w.scene.chapter||1,1,24);
export const districtName=r=>REGIONS.find(x=>x.chapter===r)?.name||'District '+r;
export function economyState(s){const e=s.economy??={version:1,goods:{metal:0,fiber:0,glass:0},districts:{},claims:[],shipments:[],delivered:[],stamps:[],flow:{earned:0,spent:0,public:0},history:[]};e.goods??={metal:0,fiber:0,glass:0};e.districts??={};e.claims??=[];e.shipments??=[];e.delivered??=[];e.stamps??=[];e.flow??={earned:0,spent:0,public:0};e.history??=[];return e;}
export function district(s,r){const e=economyState(s);return e.districts[r]??={favor:0,works:[],bought:{},imports:{},exports:{},fulfilled:{},reserve:0,donations:0};}
export const tradeAllowed=s=>s.mode!=='battle'&&!s.fieldOrigins?.active&&s.chronicle?.phase!=='past';
function record(s,text){const e=economyState(s);e.history.unshift(text);e.history=e.history.slice(0,12);}
function allowed(s,r){return tradeAllowed(s)&&Number.isInteger(r)&&r>=1&&r<=chapter(s);}
function spend(s,n){if(!Number.isSafeInteger(n)||n<0||s.gold<n)return false;s.gold-=n;economyState(s).flow.spent+=n;return true;}
function earn(s,n){s.gold+=n;economyState(s).flow.earned+=n;}
export function marketInfo(s,r){const d=district(s,r),c=chapter(s),restored=(s.regionalLife?.projects||[]).includes(r)||PHYSICAL_LORE.some(p=>p.chapter===r&&(s.physicalLore?.completed||[]).includes(p.id)),exportGood=GOODS[(r-1)%3].id,needGood=GOODS[r%3].id;return {region:r,name:districtName(r),chapter:c,exportGood,needGood,prosperity:d.works.length+(restored?1:0),favor:d.favor,works:d.works,cycle:c};}
export function quoteSupply(s,r,item,useFavor=false){const d=district(s,r),m=marketInfo(s,r),key=chapter(s)+':'+item.id,essential=['tonic','ether','revive','mossWrap'].includes(item.id),remaining=essential?Infinity:Math.max(0,3+m.prosperity+(economyState(s).stamps.includes('common-thread')?2:0)-(d.bought[key]||0));let factor=essential?1:1+(d.bought[key]||0)*.06+(r%3-1)*.04;if(d.works.includes('water')&&essential)factor*=.85;if(m.prosperity)factor*=1-Math.min(.12,m.prosperity*.03);if(useFavor&&d.favor>=2)factor*=.8;return {price:Math.max(1,Math.ceil(item.price*clamp(factor,.6,1.5))),remaining,favorCost:useFavor&&d.favor>=2?2:0};}
export function purchaseSupply(s,r,item,useFavor=false){if(!allowed(s,r)||!item||item.chapter>chapter(s))return false;const q=quoteSupply(s,r,item,useFavor),d=district(s,r);if(q.remaining<1||!spend(s,q.price))return false;d.favor-=q.favorCost;d.bought[chapter(s)+':'+item.id]=(d.bought[chapter(s)+':'+item.id]||0)+1;s.items[item.id]=(s.items[item.id]||0)+1;const contribution=Math.floor(q.price*.1);economyState(s).flow.public+=contribution;d.reserve=(d.reserve||0)+contribution;record(s,item.name+' bought in '+districtName(r)+' · '+q.price+' credits'+(q.favorCost?' + 2 reciprocity':''));return true;}
export function commodityQuote(s,r,id){if(!GOODS.some(g=>g.id===id))return null;const d=district(s,r),m=marketInfo(s,r),key=chapter(s)+':'+id;return {buy:m.exportGood===id?9:24,sell:m.needGood===id?19:4,exportLeft:Math.max(0,4-(d.exports[key]||0)),importLeft:Math.max(0,4-(d.imports[key]||0))};}
export function tradeGood(s,r,id,kind){if(!allowed(s,r))return false;const q=commodityQuote(s,r,id);if(!q)return false;const d=district(s,r),e=economyState(s),key=chapter(s)+':'+id;if(kind==='buy'){if(q.exportLeft<1||!spend(s,q.buy))return false;e.goods[id]++;d.exports[key]=(d.exports[key]||0)+1;record(s,'Packed '+id+' from '+districtName(r));return true;}if(kind!=='sell'||e.goods[id]<1||q.importLeft<1)return false;e.goods[id]--;d.imports[key]=(d.imports[key]||0)+1;earn(s,q.sell);record(s,'Sold '+id+' to '+districtName(r)+' · '+q.sell+' credits');return true;}
export function localNeed(s,r){const d=district(s,r),m=marketInfo(s,r),key=chapter(s)+':'+m.needGood;return {id:m.needGood,quantity:2,left:Math.max(0,2-(d.fulfilled[key]||0)),credits:Math.round((18+r)*(d.works.includes('commons')?1.15:1)),key};}
export function fulfillNeed(s,r){if(!allowed(s,r))return false;const n=localNeed(s,r),e=economyState(s),d=district(s,r);if(n.left<1||e.goods[n.id]<n.quantity)return false;e.goods[n.id]-=n.quantity;d.fulfilled[n.key]=(d.fulfilled[n.key]||0)+1;d.favor=Math.min(50,d.favor+3);earn(s,n.credits);record(s,districtName(r)+' received '+n.quantity+' '+n.id+' · +3 reciprocity');return true;}
export function civicCost(s,r,id){const work=CIVIC_WORKS.find(x=>x.id===id);const match=Math.min(Math.floor((80+r*10)*.25),district(s,r).reserve||0);return work?{credits:80+r*10-match,match,good:work.good,quantity:4,done:district(s,r).works.includes(id)}:null;}
export function buildCivic(s,r,id){if(!allowed(s,r))return false;const q=civicCost(s,r,id),e=economyState(s),d=district(s,r);if(!q||q.done||e.goods[q.good]<q.quantity||!spend(s,q.credits))return false;e.goods[q.good]-=q.quantity;d.reserve=Math.max(0,(d.reserve||0)-q.match);d.works.push(id);d.favor=Math.min(50,d.favor+5);e.flow.public+=q.credits;record(s,CIVIC_WORKS.find(x=>x.id===id).name+' opened in '+districtName(r));return true;}
export function craftSupply(s,r,recipe){if(!allowed(s,r)||!RECIPES.includes(recipe)||recipe.chapter>chapter(s))return false;const e=economyState(s),cost=Math.max(1,recipe.cost-(district(s,r).works.includes('workshop')?1:0));if(e.goods[recipe.good]<cost)return false;e.goods[recipe.good]-=cost;s.items[recipe.item]=(s.items[recipe.item]||0)+1;record(s,recipe.name+' crafted · '+cost+' '+recipe.good);return true;}
export function encounterSalvage(s,{key,region=chapter(s),type='patrol',core='earth'}={}){if(!tradeAllowed(s)||!['patrol','boss','rival'].includes(type)||typeof key!=='string')return null;const e=economyState(s),claim='encounter:'+key;if(e.claims.includes(claim))return null;e.claims.push(claim);const id=['tide','frost','volt','ward','shade','gravity'].includes(core)?'glass':['mend','gale'].includes(core)?'fiber':'metal',n=type==='boss'?3:1;e.goods[id]+=n;for(const shipment of e.shipments)if(shipment.protected<2&&!shipment.encounters.includes(key)){shipment.encounters.push(key);shipment.protected=Math.min(2,shipment.protected+1);}record(s,'Recovered '+n+' '+id+' · '+districtName(region));return {id,quantity:n};}
/** A paid, peaceful wild resolution can protect cargo already on this road.
 * Called after ecology settlement, while the finished battle still exists.
 * No body drops, goods, money or retroactive shipments are created here. */
export function securePeacefulShipment(s,b,result='win'){
 const ecology=b?.ecology,e=s?.economy,region=b?.context?.chapter??b?.chapter;
 if(!ecology?.enabled||!ecology.settled||ecology.cargoPassageSettled)return null;
 ecology.cargoPassageSettled=true;
 if(result!=='win'||b?.ended!=='win'||b.context?.wild!==true||b.context.friendly||b.context.tutorial||s.fieldOrigins?.active||s.chronicle?.phase==='past'||!Number.isInteger(region)||region<1||region>24||!Array.isArray(e?.shipments)||!e.shipments.length)return null;
 const records=ecology.creatures||[],enemies=b.enemies||[];
 if(!records.length||records.length!==enemies.length||records.some(r=>{
  const actor=enemies.find(a=>a.id===r.actorId),memory=s.creatureMemory?.individuals?.find(m=>m.key===r.key&&m.lastEncounter===ecology.encounterId);
  return !actor||actor.boss||actor.hp<=0||!actor.withdrawn||!r.withdrawn||r.injuredByHero||r.harmCount>0||r.stolenTool||!memory||!['peaceful','escaped'].includes(memory.lastOutcome);
 })||!records.some(r=>r.fed||r.calmed||r.nestSafe||r.rescued||r.trust>=2))return null;
 const key='peaceful:'+ecology.encounterId;
 if((e.claims||[]).includes(key))return null;
 const shipments=e.shipments.filter(q=>(q.source===region||q.destination===region)&&q.protected<2&&Array.isArray(q.encounters)&&!q.encounters.includes(key));
 if(!shipments.length)return null;
 e.claims??=[];e.claims.push(key);
 for(const q of shipments){q.encounters.push(key);q.protected=Math.min(2,q.protected+1);}
 const label='Peaceful passage keeps the delivery road open · '+shipments.length+' shipment'+(shipments.length===1?'':'s')+' protected';
 record(s,label);b.event?.({type:'city-answer',contribution:'passage',kind:'route',action:'peaceful-passage',actor:b.heroes?.find(h=>h.hp>0),label,shipmentIds:shipments.map(q=>q.id)});
 return {encounterId:ecology.encounterId,shipments:shipments.map(q=>q.id),label};
}
export function gatherTradeGoods(s,region,source){if(!tradeAllowed(s)||typeof source!=='string')return false;const e=economyState(s),key='gather:'+source;if(e.claims.includes(key))return false;e.claims.push(key);e.goods.fiber++;record(s,'A gathered fibre bundle joins the trade satchel.');return true;}
export function routeOffer(s,r){const e=economyState(s),destination=r===1?2:r-1,good=GOODS[(r-1)%3].id,id=chapter(s)+':'+r+'>'+destination;return {id,source:r,destination,good,quantity:2,credits:60+r*8,available:destination<=chapter(s)&&!e.delivered.includes(id)&&!e.shipments.some(x=>x.id===id),label:districtName(r)+' → '+districtName(destination)};}
export function acceptShipment(s,r){if(!allowed(s,r))return false;const q=routeOffer(s,r),e=economyState(s),capacity=e.stamps.includes('three-hands')?2:1;if(!q.available||e.shipments.length>=capacity||e.goods[q.good]<q.quantity)return false;e.goods[q.good]-=q.quantity;e.shipments.push({...q,protected:0,encounters:[]});record(s,'Cargo loaded · '+q.label+' · protect it through two different encounters');return true;}
export function cancelShipment(s,id){const e=economyState(s),q=e.shipments.find(x=>x.id===id);if(!q||!tradeAllowed(s))return false;e.goods[q.good]+=q.quantity;e.shipments=e.shipments.filter(x=>x!==q);record(s,'Shipment unpacked; all materials returned.');return true;}
export function deliverShipment(s,r,id){if(!allowed(s,r))return false;const e=economyState(s),q=e.shipments.find(x=>x.id===id);if(!q||q.destination!==r||q.protected<2||e.delivered.includes(id))return false;e.shipments=e.shipments.filter(x=>x!==q);e.delivered.push(id);earn(s,q.credits);district(s,r).favor=Math.min(50,district(s,r).favor+4);district(s,q.source).favor=Math.min(50,district(s,q.source).favor+2);for(const stamp of STAMPS)if(e.delivered.length>=stamp.at&&!e.stamps.includes(stamp.id))e.stamps.push(stamp.id);record(s,'Delivered to '+districtName(r)+' · '+q.credits+' credits · both communities remember');return true;}
export function economyLegacy(s){const e=s?.economy;return {stamps:[...(e?.stamps||[])],works:Object.values(e?.districts||{}).reduce((n,d)=>n+d.works.length,0)};}
export function awardReciprocity(s,r,source,amount=2){if(!tradeAllowed(s)||!Number.isInteger(r)||r<1||r>24||typeof source!=='string')return false;const e=economyState(s),key='kindness:'+source;if(e.claims.includes(key))return false;e.claims.push(key);district(s,r).favor=Math.min(50,district(s,r).favor+clamp(Math.floor(amount),1,5));record(s,districtName(r)+' remembers your work · local reciprocity earned');return true;}
export function economicComment(s,r){const d=s.economy?.districts?.[r];if(!d)return '';if(d.works.includes('commons'))return 'The commons keeps a dry place for whoever finishes the late shift. Nobody has to buy a chair here.';if(d.works.includes('water'))return 'Clean water has made remedies cheaper. The keepers pass that saving along instead of keeping it.';if(d.works.includes('workshop'))return 'The repair workshop shares its tools. A bundle goes further when everyone can use the same good needle.';if(d.favor>=3)return 'People remember what reached their hands. You can ask the exchange for a neighbour’s price.';return '';}
export function validateEconomy(s){const e=s.economy;if(!e)return true;const valid=n=>Number.isSafeInteger(n)&&n>=0&&n<=1000000000;if(e.version!==1||!e.goods||GOODS.some(g=>!valid(e.goods[g.id]))||!e.districts||!Array.isArray(e.claims)||!Array.isArray(e.shipments)||e.shipments.length>2||!Array.isArray(e.delivered)||!Array.isArray(e.stamps)||e.stamps.some(id=>!STAMPS.some(x=>x.id===id)))throw Error('Invalid trade satchel');for(const [id,d]of Object.entries(e.districts)){if(!Number.isInteger(+id)||+id<1||+id>24||!valid(d.favor)||d.favor>50||!Array.isArray(d.works)||new Set(d.works).size!==d.works.length||d.works.some(id=>!CIVIC_WORKS.some(w=>w.id===id)))throw Error('Invalid district account');if(d.reserve!==undefined&&!valid(d.reserve))throw Error('Invalid community reserve');for(const key of ['bought','imports','exports','fulfilled'])if(!d[key]||Object.values(d[key]).some(n=>!valid(n)))throw Error('Invalid market inventory');}for(const q of e.shipments)if(typeof q.id!=='string'||!GOODS.some(g=>g.id===q.good)||q.quantity!==2||!valid(q.credits)||!valid(q.protected)||q.protected>2||!Array.isArray(q.encounters)||!Number.isInteger(q.destination)||q.destination<1||q.destination>24)throw Error('Invalid consignment');return true;}
